using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MagistralReplicationActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/MagistralReplicationActionCustomDescription", order = 0)]
public class MagistralReplicationActionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		MagistralReplicationAction magistralReplicationAction = battleAction as MagistralReplicationAction;
		return magistralReplicationAction.MagistralReplicationLogicAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)) + "\n" + base.localizationManager.GetLocalizedDecreaseEffect(magistralReplicationAction.PlayerEffectsList.AstriumEffect, magistralReplicationAction.DecreaseAstriumAmount, playerEffect: true);
	}
}
